//! Safe wrapper over the official esp-sr WakeNet C API.
//!
//! The bindings are generated by esp-idf-sys from `src/esp_sr_bindings.h`,
//! which just includes the official headers — there is no custom C shim in
//! this project any more.

use core::ffi::{c_char, c_void};

use esp_idf_sys as sys;

pub struct WakeNet {
    models: *mut sys::srmodel_list_t,
    iface: *const sys::esp_wn_iface_t,
    model: *mut sys::model_iface_data_t,
    chunk: usize,
}

impl WakeNet {
    /// Initialise WakeNet from the `model` partition, picking the first model
    /// whose name contains `keyword` (e.g. `"xiaotexiaote"`).
    pub fn new(keyword: &str) -> Result<Self, String> {
        let mut keyword_z = Vec::with_capacity(keyword.len() + 1);
        keyword_z.extend_from_slice(keyword.as_bytes());
        keyword_z.push(0);

        unsafe {
            let models = sys::esp_srmodel_init(c"model".as_ptr());
            if models.is_null() {
                return Err(
                    "esp_srmodel_init(\"model\") returned NULL (model partition missing?)".into(),
                );
            }

            let name = sys::esp_srmodel_filter(models, c"wn".as_ptr(), keyword_z.as_ptr() as *const c_char);
            if name.is_null() {
                sys::esp_srmodel_deinit(models);
                return Err(format!("no WakeNet model containing \"{keyword}\" in model partition"));
            }

            let iface = sys::esp_wn_handle_from_name(name);
            if iface.is_null() {
                sys::esp_srmodel_deinit(models);
                return Err(format!(
                    "esp_wn_handle_from_name({}) failed",
                    c_str(name)
                ));
            }

            let Some(create) = (*iface).create else {
                sys::esp_srmodel_deinit(models);
                return Err("esp_wn_iface_t::create is NULL".into());
            };
            let model = create(name as *const c_void, sys::det_mode_t_DET_MODE_95);
            if model.is_null() {
                sys::esp_srmodel_deinit(models);
                return Err(format!("wakenet create({}) failed", c_str(name)));
            }

            let chunk = (*iface)
                .get_samp_chunksize
                .map(|f| f(model))
                .unwrap_or(0);
            if chunk <= 0 {
                if let Some(destroy) = (*iface).destroy {
                    destroy(model);
                }
                sys::esp_srmodel_deinit(models);
                return Err("get_samp_chunksize returned 0".into());
            }

            println!(
                "[idf-kws] model={} chunk={} rate={}",
                c_str(name),
                chunk,
                (*iface).get_samp_rate.map(|f| f(model)).unwrap_or(0)
            );

            Ok(Self {
                models,
                iface,
                model,
                chunk: chunk as usize,
            })
        }
    }

    pub fn chunk_size(&self) -> usize {
        self.chunk
    }

    /// Feed one chunk of 16 kHz mono samples. Returns true on wake word.
    pub fn detect(&mut self, pcm: &[i16]) -> bool {
        debug_assert_eq!(pcm.len(), self.chunk);
        unsafe {
            let Some(detect) = (*self.iface).detect else {
                return false;
            };
            detect(self.model, pcm.as_ptr() as *mut i16) == sys::wakenet_state_t_WAKENET_DETECTED
        }
    }

    /// Clear the detector state (e.g. after TTS playback) without recreating the model.
    #[allow(dead_code)]
    pub fn reset(&mut self) {
        unsafe {
            if let Some(clean) = (*self.iface).clean {
                clean(self.model);
            }
        }
    }
}

impl Drop for WakeNet {
    fn drop(&mut self) {
        unsafe {
            if !self.model.is_null() {
                if let Some(destroy) = (*self.iface).destroy {
                    destroy(self.model);
                }
            }
            if !self.models.is_null() {
                sys::esp_srmodel_deinit(self.models);
            }
        }
    }
}

unsafe fn c_str(ptr: *const c_char) -> String {
    if ptr.is_null() {
        return "<null>".into();
    }
    core::ffi::CStr::from_ptr(ptr).to_string_lossy().into_owned()
}
